// Access to Chummer5a reference data (skills, metatypes, items) for the .chum5 import/export.
// Primary source: the Chummer data folder (../Chummer5.226.0/data, or env CHUMMER_DATA_DIR), parsed lazily.
// Fallbacks when it is absent (the Docker image has no Chummer folder): snapshot.json (skills, metatypes, grades and the
// Fake SIN / Fake License / Custom Item gear nodes — generated by build-snapshot.ts) and the app catalog
// (data/catalog/*.json, whose ids ARE Chummer GUIDs) for item names/stats (findDataItem → catalogNode).
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { parseXml, el, type Element } from './xml.ts';
import type { CatalogItem } from '../../../shared/types.ts';
import { categoryToSkill } from '../../../client/modules/sheet/sheet-data.ts';

const HERE = path.dirname(fileURLToPath(import.meta.url));
export const APP_ROOT = path.resolve(HERE, '..', '..', '..');
const CATALOG_DIR = path.join(APP_ROOT, 'data', 'catalog');

export function chummerDataDir(): string {
  return process.env.CHUMMER_DATA_DIR ? path.resolve(process.env.CHUMMER_DATA_DIR) : path.resolve(APP_ROOT, '..', 'Chummer5.226.0', 'data');
}

const docCache = new Map<string, Element | null>();
/** Root element of a Chummer data file (e.g. 'weapons.xml'), or null when unavailable. */
export function dataRoot(file: string): Element | null {
  if (docCache.has(file)) return docCache.get(file) ?? null;
  let root: Element | null = null;
  try {
    root = parseXml(fs.readFileSync(path.join(chummerDataDir(), file), 'utf8')).root;
  } catch {
    root = null;
  }
  docCache.set(file, root);
  return root;
}

/** Chummer active skill (skills.xml <skill>). */
export interface ChummerSkillDef {
  id: string;
  name: string;
  attr: string;
  category: string;
  group: string;
  default: boolean;
  exotic: boolean;
  source: string;
}
/** Chummer knowledge skill (skills.xml <knowledgeskills>). */
export interface ChummerKnowledgeDef {
  id: string;
  name: string;
  attr: string;
  category: string;
}
export interface SkillsData {
  active: ChummerSkillDef[];
  groups: string[];
  knowledge: ChummerKnowledgeDef[];
}
/** skillsData(): the lists plus lookup maps. */
export interface SkillsIndex extends SkillsData {
  byId: Map<string, ChummerSkillDef>;
  byName: Map<string, ChummerSkillDef>;
  knoByName: Map<string, ChummerKnowledgeDef>;
}
/** Attribute limits of a metatype. */
export interface AttrLimits {
  min: number;
  max: number;
  aug: number;
}
export interface MetatypeData {
  id: string;
  name: string;
  category: string;
  karma: number;
  walk: string;
  run: string;
  sprint: string;
  attrs: Record<string, AttrLimits>;
}
/** Cyberware/bioware grade: id and essence multiplier. */
export interface GradeInfo {
  id: string;
  ess: number;
}
/** snapshot.json (see build-snapshot.ts). */
export interface ChummerSnapshot {
  generated?: string;
  source?: string;
  skills?: SkillsData;
  metatypes?: MetatypeData[];
  grades?: Record<string, GradeInfo>;
  /** Raw XML of the gear.xml nodes in BUILTIN_GEAR (Fake SIN, Fake License, Custom Item). */
  gear?: string[];
}

/** gear.xml nodes the export needs by name even without the Chummer data folder (kept in snapshot.json). */
export const BUILTIN_GEAR = ['Fake SIN', 'Fake License', 'Custom Item'];

let snapshotCache: ChummerSnapshot | null | undefined;
export function snapshot(): ChummerSnapshot | null {
  if (snapshotCache === undefined) {
    try {
      snapshotCache = JSON.parse(fs.readFileSync(path.join(HERE, 'snapshot.json'), 'utf8')) as ChummerSnapshot;
    } catch {
      snapshotCache = null;
    }
  }
  return snapshotCache;
}

export const norm = (s: unknown): string =>
  String(s ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .replace(/[’`]/g, "'")
    .toLowerCase()
    .replace(/\s+/g, ' ')
    .trim();

/** norm() without punctuation: "Yeux cybernétiques (système de base)" ≈ "Yeux cybernétiques, système de base". */
export const loose = (s: unknown): string => norm(s).replace(/[^a-z0-9]+/g, ' ').trim();

// ---------------------------------------------------------------------------
// Skills
// ---------------------------------------------------------------------------
let skillsCache: SkillsIndex | null = null;
/** { active: [{ id, name, attr, category, group, default, exotic }], groups: [name], knowledge: [{ id, name, attr, category }] } */
export function skillsData(): SkillsIndex {
  if (skillsCache) return skillsCache;
  const root = dataRoot('skills.xml');
  let lists: SkillsData;
  if (root) {
    const active = (root.child('skills')?.all('skill') || []).map((s) => ({
      id: s.val('id').toLowerCase(), name: s.val('name'), attr: s.val('attribute'), category: s.val('category'), group: s.val('skillgroup'),
      default: s.val('default') === 'True', exotic: s.val('exotic') === 'True', source: s.val('source'),
    }));
    const groups = (root.child('skillgroups')?.all('name') || []).map((g) => g.text);
    const knowledge = (root.child('knowledgeskills')?.all('skill') || []).map((s) => ({ id: s.val('id').toLowerCase(), name: s.val('name'), attr: s.val('attribute'), category: s.val('category') }));
    lists = { active, groups, knowledge };
  } else {
    const snap = snapshot();
    lists = snap?.skills || { active: [], groups: [], knowledge: [] };
  }
  // Same object as `lists` (the snapshot's own object when it comes from there), maps added on it.
  const idx = lists as SkillsIndex;
  idx.byId = new Map(idx.active.map((s) => [s.id, s]));
  idx.byName = new Map(idx.active.map((s) => [norm(s.name), s]));
  idx.knoByName = new Map(idx.knowledge.map((s) => [norm(s.name), s]));
  skillsCache = idx;
  return skillsCache;
}

/** App skill id (shared/sr5.js) from a Chummer skill name. */
export function appSkillId(chummerName: unknown): string {
  const n = String(chummerName || '');
  if (/^Exotic (Melee|Ranged) Weapon/i.test(n)) return 'exotic_weapon';
  return (
    n
      .normalize('NFD')
      .replace(/[̀-ͯ]/g, '')
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '_')
      .replace(/^_|_$/g, '') || 'x'
  );
}

/** Chummer skill definition for an app skill id (or a Chummer/English name). */
export function chummerSkillFor(appId: string, name?: string): ChummerSkillDef | null {
  const sd = skillsData();
  if (appId === 'exotic_weapon') return sd.byName.get('exotic ranged weapon') || null;
  for (const s of sd.active) if (appSkillId(s.name) === appId) return s;
  if (name) return sd.byName.get(norm(name)) || null;
  return null;
}

// ---------------------------------------------------------------------------
// Metatypes
// ---------------------------------------------------------------------------
export const METATYPE_EN: Record<string, string> = { Humain: 'Human', Elfe: 'Elf', Nain: 'Dwarf', Ork: 'Ork', Troll: 'Troll' };
export const METATYPE_FROM_EN: Record<string, string> = { Human: 'Humain', Elf: 'Elfe', Dwarf: 'Nain', Ork: 'Ork', Troll: 'Troll' };
const ATTR_KEYS: Record<string, string> = { BOD: 'bod', AGI: 'agi', REA: 'rea', STR: 'str', CHA: 'cha', INT: 'int', LOG: 'log', WIL: 'wil', EDG: 'edg', MAG: 'mag', RES: 'res', ESS: 'ess', DEP: 'dep', INI: 'ini' };

const metaCache = new Map<string, MetatypeData | null>();
/** { id, name, category, karma, walk, run, sprint, attrs: { BOD: { min, max, aug }, … } } or null. */
export function metatypeData(nameEn: string): MetatypeData | null {
  const key = norm(nameEn || 'Human');
  if (metaCache.has(key)) return metaCache.get(key) ?? null;
  let out: MetatypeData | null = null;
  const root = dataRoot('metatypes.xml');
  if (root) {
    const m = (root.child('metatypes')?.all('metatype') || []).find((x) => norm(x.val('name')) === key);
    if (m) {
      const attrs: Record<string, AttrLimits> = {};
      for (const [k, p] of Object.entries(ATTR_KEYS)) {
        attrs[k] = { min: Number(m.val(`${p}min`)) || 0, max: Number(m.val(`${p}max`)) || 0, aug: Number(m.val(`${p}aug`)) || 0 };
      }
      out = { id: m.val('id').toLowerCase(), name: m.val('name'), category: m.val('category'), karma: Number(m.val('karma')) || 0, walk: m.val('walk'), run: m.val('run'), sprint: m.val('sprint'), attrs };
    }
  }
  if (!out) out = snapshot()?.metatypes?.find((x) => norm(x.name) === key) || null;
  metaCache.set(key, out);
  return out;
}

// ---------------------------------------------------------------------------
// Items (data XML nodes + app catalog)
// ---------------------------------------------------------------------------
/** Chummer data kinds (DATA_FILES keys). */
export type DataKind =
  | 'weapons' | 'armor' | 'gear' | 'cyberware' | 'bioware' | 'qualities' | 'powers' | 'spells' | 'lifestyles' | 'vehicles' | 'complexforms'
  | 'lifestylequalities' | 'accessories' | 'armormods' | 'vehiclemods' | 'martialarts' | 'techniques';

/** kind → [file, container, node] */
export const DATA_FILES: Record<DataKind, [string, string, string]> = {
  weapons: ['weapons.xml', 'weapons', 'weapon'],
  armor: ['armor.xml', 'armors', 'armor'],
  gear: ['gear.xml', 'gears', 'gear'],
  cyberware: ['cyberware.xml', 'cyberwares', 'cyberware'],
  bioware: ['bioware.xml', 'biowares', 'bioware'],
  qualities: ['qualities.xml', 'qualities', 'quality'],
  powers: ['powers.xml', 'powers', 'power'],
  spells: ['spells.xml', 'spells', 'spell'],
  lifestyles: ['lifestyles.xml', 'lifestyles', 'lifestyle'],
  vehicles: ['vehicles.xml', 'vehicles', 'vehicle'],
  complexforms: ['complexforms.xml', 'complexforms', 'complexform'],
  lifestylequalities: ['lifestyles.xml', 'qualities', 'quality'],
  accessories: ['weapons.xml', 'accessories', 'accessory'],
  armormods: ['armor.xml', 'mods', 'mod'],
  vehiclemods: ['vehicles.xml', 'mods', 'mod'],
  martialarts: ['martialarts.xml', 'martialarts', 'martialart'],
  techniques: ['martialarts.xml', 'techniques', 'technique'],
};

interface DataIndex {
  byId: Map<string, Element>;
  byName: Map<string, Element>;
  /** The Chummer data file is missing: lookups fall back to snapshot.json and the app catalog (fallbackItem). */
  fallback: boolean;
}
const indexCache = new Map<string, DataIndex>();
function dataIndex(kind: DataKind): DataIndex {
  const cached = indexCache.get(kind);
  if (cached) return cached;
  const spec = DATA_FILES[kind];
  const root = spec && dataRoot(spec[0]);
  const idx: DataIndex = { byId: new Map(), byName: new Map(), fallback: !root };
  const put = (n: Element) => {
    const id = n.val('id').toLowerCase();
    if (id) idx.byId.set(id, n);
    const nm = norm(n.val('name'));
    if (nm && !idx.byName.has(nm)) idx.byName.set(nm, n);
  };
  for (const n of root?.child(spec[1])?.all(spec[2]) || []) put(n);
  if (!root && kind === 'gear') {
    for (const xml of snapshot()?.gear || []) {
      try {
        put(parseXml(xml).root);
      } catch {
        /* a broken snapshot entry only loses that item */
      }
    }
  }
  indexCache.set(kind, idx);
  return idx;
}

// ---------------------------------------------------------------------------
// Fallback data nodes from the app catalog (no Chummer data folder, e.g. the Docker image)
// ---------------------------------------------------------------------------
/** Kinds whose app catalog entries carry enough to stand in for the Chummer node (id, stats, formulas). */
const CATALOG_NODE_KINDS = new Set<DataKind>(['weapons', 'armor', 'cyberware', 'bioware', 'gear']);

/** App weapon skill id → Chummer skill name (for <useskill>). */
const WEAPON_SKILL_EN: Record<string, string> = {
  unarmed_combat: 'Unarmed Combat', blades: 'Blades', clubs: 'Clubs', pistols: 'Pistols', automatics: 'Automatics', longarms: 'Longarms',
  heavy_weapons: 'Heavy Weapons', throwing_weapons: 'Throwing Weapons', archery: 'Archery', gunnery: 'Gunnery',
};

const str = (v: unknown): string => (v === undefined || v === null ? '' : String(v));

/** Chummer <avail> from the catalog: "5R", "(Rating * 3)F", "FixedValues(8R,12R,20R)". */
function catalogAvail(e: AppCatalogEntry): string {
  const f = str(e.availFormula);
  if (!f) return str(e.avail) || '0';
  const legal = str(e.legality);
  const fixed = f.match(/^FixedValues\((.*)\)$/);
  if (fixed) return `FixedValues(${fixed[1].split(',').map((v) => v.trim() + legal).join(',')})`;
  return f + legal;
}

/** Chummer <cost> from the catalog: "725", "Rating * 250", "Variable(20-100000)". */
function catalogCost(e: AppCatalogEntry): string {
  if (e.costFormula) return str(e.costFormula);
  if (Array.isArray(e.costRange) && e.costRange.length === 2) return `Variable(${e.costRange[0]}-${e.costRange[1]})`;
  return str(e.cost ?? 0);
}

/**
 * A Chummer-like data node built from an app catalog entry, with the fields the export copies (export.ts cloneData,
 * buildWeapon, buildWare…) and the import reads back (parse.ts). Bonus nodes are not rebuilt: Chummer's own data has them.
 */
function catalogNode(kind: DataKind, e: AppCatalogEntry): Element {
  const s = (e.stats || {}) as Record<string, unknown>;
  const kids: Element[] = [el('id', e.id), el('name', e.name), el('category', str(e.category))];
  const add = (k: string, v: unknown) => {
    if (v !== undefined && v !== null && v !== '') kids.push(el(k, str(v)));
  };
  const rating = e.rating as { min?: number; max?: number } | undefined;
  if (kind === 'weapons') {
    const melee = s.type === 'melee';
    const ap = Number(s.ap);
    add('type', melee ? 'Melee' : 'Ranged');
    add('conceal', s.conceal ?? 0);
    add('accuracy', s.accuracy ?? 0);
    add('reach', s.reach ?? 0);
    add('damage', str(s.damage).replace(/\bSTR\b/g, '{STR}'));
    add('ap', Number.isFinite(ap) && typeof s.ap === 'number' ? (ap > 0 ? `+${ap}` : String(ap)) : str(s.ap) || '0');
    add('mode', melee ? '0' : str(s.mode) || '0');
    add('rc', s.rc ?? 0);
    add('ammo', str(s.ammo) || '0');
    // <useskill> only when the category does not give the skill (the catalog skill comes from Chummer's useskill, else
    // its category: tools/build-catalog.ts); exotic skills are left to the category (Chummer needs the weapon name too).
    const skill = str(s.skill);
    if (WEAPON_SKILL_EN[skill] && skill !== categoryToSkill(e.category)) add('useskill', WEAPON_SKILL_EN[skill]);
  } else if (kind === 'armor') {
    if (rating?.max) add('rating', rating.max);
    add('armor', s.stack ? `+${s.armor ?? 0}` : (s.armor ?? 0));
    add('armorcapacity', s.capacity ?? 0);
  } else if (kind === 'cyberware' || kind === 'bioware') {
    add('ess', e.essence ?? 0);
    add('capacity', s.capacity ?? 0);
    if (rating?.max) add('rating', rating.max);
    if (rating?.min) add('minrating', rating.min);
  } else if (kind === 'gear') {
    add('rating', rating?.max ?? 0);
    if (rating?.min && rating.min > 1) add('minrating', rating.min);
    add('capacity', s.capacity);
    add('devicerating', s.deviceRating);
    add('attack', s.attack);
    add('sleaze', s.sleaze);
    add('dataprocessing', s.dataProcessing);
    add('firewall', s.firewall);
  }
  add('avail', catalogAvail(e));
  add('cost', catalogCost(e));
  add('source', e.source || 'SR5');
  add('page', e.page ?? 0);
  if (kind === 'weapons') {
    const included = (Array.isArray(s.included) ? s.included : []) as Array<{ name?: string }>;
    if (included.length) kids.push(el('accessories', included.filter((a) => a.name).map((a) => el('accessory', [el('name', str(a.name))]))));
    const mounts = (Array.isArray(s.mounts) ? s.mounts : []) as string[];
    if (mounts.length) kids.push(el('accessorymounts', mounts.map((m) => el('mount', m))));
  }
  return el(DATA_FILES[kind][2], kids);
}

const fallbackCache = new Map<string, Element | null>();
/** Data node stand-in when the Chummer file is missing: snapshot built-ins (by name), else the app catalog. */
function fallbackItem(kind: DataKind, idx: DataIndex, { id, name }: ItemKey): Element | null {
  if (id) {
    const n = idx.byId.get(String(id).toLowerCase());
    if (n) return n;
  }
  if (name) {
    const n = idx.byName.get(norm(name));
    if (n) return n;
  }
  if (!CATALOG_NODE_KINDS.has(kind)) return null;
  // By GUID, else by the exact English name (the Chummer data lookup is by English name too).
  let e = id ? findCatalogEntry(kind, { id }) : null;
  if (!e && name) {
    for (const c of KIND_CATALOGS[kind]) {
      const hit = appCatalog(c).list.find((x) => norm(x.name) === norm(name));
      if (hit) {
        e = hit;
        break;
      }
    }
  }
  if (!e?.id) return null;
  const key = `${kind}:${String(e.id).toLowerCase()}`;
  if (!fallbackCache.has(key)) fallbackCache.set(key, catalogNode(kind, e));
  return fallbackCache.get(key) ?? null;
}

/** Item lookup key: Chummer GUID and/or (English or French) name. */
export interface ItemKey {
  id?: string | null;
  name?: string | null;
}

/**
 * Chummer data node for an item: by GUID, else by (English) name. Without the Chummer data file, a stand-in from
 * snapshot.json (BUILTIN_GEAR) or the app catalog (weapons, armor, 'ware, gear), so the export keeps sourceids, SINs and essence.
 */
export function findDataItem(kind: DataKind, { id, name }: ItemKey = {}): Element | null {
  const idx = dataIndex(kind);
  if (idx.fallback) return fallbackItem(kind, idx, { id, name });
  if (id) {
    const n = idx.byId.get(String(id).toLowerCase());
    if (n) return n;
  }
  if (name) return idx.byName.get(norm(name)) || null;
  return null;
}

/** Cyberware/bioware grade names → { ess multiplier } from the data file (fallback: SR5 core values). */
export function gradeTable(kind = 'cyberware'): Record<string, GradeInfo> {
  const root = dataRoot(kind === 'bioware' ? 'bioware.xml' : 'cyberware.xml');
  const out: Record<string, GradeInfo> = {};
  for (const g of root?.child('grades')?.all('grade') || []) out[g.val('name')] = { id: g.val('id'), ess: Number(g.val('ess')) || 1 };
  if (!Object.keys(out).length) Object.assign(out, snapshot()?.grades || {});
  return out;
}

/** App catalog entry as read by the Chummer interop (martial arts also carry their techniques at the top level in old files). */
export type AppCatalogEntry = CatalogItem & { techniques?: unknown; stats?: { techniques?: unknown } };

/** A loaded app catalog file with its lookup maps. */
export interface AppCatalog {
  list: AppCatalogEntry[];
  byId: Map<string, AppCatalogEntry>;
  byName: Map<string, AppCatalogEntry>;
  byLoose: Map<string, AppCatalogEntry>;
  byStem: Map<string, AppCatalogEntry>;
}

// App catalog (data/catalog/<name>.json)
const catCache = new Map<string, AppCatalog>();
export function appCatalog(name: string): AppCatalog {
  const cached = catCache.get(name);
  if (cached) return cached;
  let list: AppCatalogEntry[] = [];
  try {
    const raw = JSON.parse(fs.readFileSync(path.join(CATALOG_DIR, `${name}.json`), 'utf8'));
    list = Array.isArray(raw) ? raw : raw.items || [];
  } catch {
    list = [];
  }
  const byId = new Map(list.map((e) => [String(e.id).toLowerCase(), e]));
  const byName = new Map<string, AppCatalogEntry>();
  const byLoose = new Map<string, AppCatalogEntry>();
  const byStem = new Map<string, AppCatalogEntry>();
  const put = (m: Map<string, AppCatalogEntry>, k: string, e: AppCatalogEntry) => k && !m.has(k) && m.set(k, e);
  for (const e of list) {
    for (const nm of [e.name, e.nameFr]) {
      put(byName, norm(nm), e);
      put(byLoose, loose(nm), e);
      put(byStem, loose(String(nm || '').replace(/\s*\([^)]*\)\s*$/, '')), e);
    }
  }
  const out: AppCatalog = { list, byId, byName, byLoose, byStem };
  catCache.set(name, out);
  return out;
}

/** Catalog file names that can hold a given Chummer data kind. */
export const KIND_CATALOGS: Record<DataKind, string[]> = {
  weapons: ['weapons'], armor: ['armor'], gear: ['gear', 'programs'], cyberware: ['cyberware'], bioware: ['bioware'],
  qualities: ['qualities'], powers: ['powers'], spells: ['spells'], lifestyles: ['lifestyles'], vehicles: ['vehicles'], complexforms: [],
  lifestylequalities: ['lifestylequalities'], accessories: ['accessories'], armormods: ['armormods'], vehiclemods: ['vehiclemods'], martialarts: ['martialarts'], techniques: [],
};

/** App catalog entry by GUID or by English/French name. */
export function findCatalogEntry(kind: DataKind, { id, name }: ItemKey = {}): AppCatalogEntry | null {
  for (const c of KIND_CATALOGS[kind] || []) {
    const cat = appCatalog(c);
    if (id) {
      const e = cat.byId.get(String(id).toLowerCase());
      if (e) return e;
    }
  }
  if (name) {
    for (const map of ['byName', 'byLoose', 'byStem'] as const) {
      for (const c of KIND_CATALOGS[kind] || []) {
        const e = appCatalog(c)[map].get(map === 'byName' ? norm(name) : loose(name));
        if (e) return e;
      }
    }
  }
  return null;
}

/** French display name for a Chummer GUID (app catalog), or null. */
export function frenchName(kind: DataKind, id: string | null | undefined): string | null {
  const e = id ? findCatalogEntry(kind, { id }) : null;
  return e?.nameFr || null;
}

/** French category for a Chummer GUID (app catalog), or null. */
export function frenchCategory(kind: DataKind, id: string | null | undefined): string | null {
  const e = id ? findCatalogEntry(kind, { id }) : null;
  return e?.categoryFr || null;
}
